import React from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, spring, interpolate } from '../remotionShim';
{/* Start Google Fonts Loader */ }
const useFontLoader = (fonts: string[]) => {
  const stableFonts = React.useMemo(() => {
    const unique = [...new Set(fonts.map(f => f.trim()))].sort();
    return unique;
  }, [fonts.join("|")]); // super light + stable

  React.useEffect(() => {
    const unloaded = stableFonts.filter(
      (font) =>
        !document.querySelector(
          `link[href*="${font.replace(/\s+/g, "+")}"]`
        )
    );

    if (unloaded.length === 0) return;

    const url = `https://fonts.googleapis.com/css2?${unloaded
      .map((font) => `family=${font.replace(/\s+/g, "+")}:wght@400;600;700`)
      .join("&")}&display=swap`;

    const link = document.createElement("link");
    link.rel = "stylesheet";
    link.href = url;

    document.head.appendChild(link);
  }, [stableFonts]);
};
{/* End Google Fonts Loader */ }



export type TechLowerThirdProps = Record<string, any>;

const TechLowerThird: React.FC<TechLowerThirdProps> = ({
  backgroundColor = "#050505",
  transparentBackground = true,
  durationInSeconds = 6,
  nameText = "Alex Mercer",
  titleText = "Lead Systems Engineer",
  logoImage = "https://cdn-icons-png.flaticon.com/512/1118/1118955.png",
  logoSize = 55,
  primaryBoxColor = "#0A0A0A",
  accentColor = "#00E5FF",
  panelColor = "rgba(10, 12, 16, 0.85)",
  textColor = "#FFFFFF",
  titleColor = "#8A94A6",
}) => {
  {/* Load Google Fonts */ }
  useFontLoader(["Space Grotesk", "Inter"]);
  {/* End Load Google Fonts */ }

  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  const bgColor = transparentBackground ? "transparent" : backgroundColor;

  // Animation Timing Calculation
  const exitStartFrame = durationInSeconds * fps - 35; // Begin exit sequence ~1.1s before end

  // --- LOGO BOX ANIMATION ---
  const logoEntry = spring({ frame: frame - 5, fps, config: { damping: 14, mass: 0.9 } });
  const logoExit = spring({ frame: frame - exitStartFrame, fps, config: { damping: 14, mass: 0.9 } });
  const logoAnim = Math.max(0, logoEntry - logoExit);

  const logoScale = interpolate(logoAnim, [0, 1], [0, 1], { extrapolateRight: "clamp" });
  const logoRotate = interpolate(logoAnim, [0, 1], [-90, 0], { extrapolateRight: "clamp" });

  // --- TEXT PANEL ANIMATION ---
  const panelEntry = spring({ frame: frame - 15, fps, config: { damping: 16, mass: 1 } });
  const panelExit = spring({ frame: frame - exitStartFrame + 5, fps, config: { damping: 16, mass: 1 } });
  const panelAnim = Math.max(0, panelEntry - panelExit);

  const targetPanelWidth = width * 0.55;
  const panelWidth = interpolate(panelAnim, [0, 1], [0, targetPanelWidth], { extrapolateRight: "clamp" });

  // --- TEXT CONTENT ANIMATION ---
  const textEntry = spring({ frame: frame - 22, fps, config: { damping: 12, mass: 0.8 } });
  const textExit = spring({ frame: frame - exitStartFrame + 10, fps, config: { damping: 12, mass: 0.8 } });
  const textAnim = Math.max(0, textEntry - textExit);

  const textOpacity = interpolate(textAnim, [0, 1], [0, 1], { extrapolateRight: "clamp" });
  const textTranslateY = interpolate(textAnim, [0, 1], [20, 0], { extrapolateRight: "clamp" });

  // --- DECORATIVE LINE ANIMATION ---
  const lineEntry = spring({ frame: frame - 28, fps, config: { damping: 15 } });
  const lineExit = spring({ frame: frame - exitStartFrame + 15, fps, config: { damping: 15 } });
  const lineAnim = Math.max(0, lineEntry - lineExit);
  const lineWidth = interpolate(lineAnim, [0, 1], [0, targetPanelWidth], { extrapolateRight: "clamp" });

  // Dynamic Sizes
  const boxSize = height * 0.20;
  const panelHeight = height * 0.17;
  const safeLeft = width * 0.08;
  const safeBottom = height * 0.12;

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor, transition: "none" }}>
      <div
        style={{
          position: "absolute",
          left: safeLeft,
          bottom: safeBottom,
          display: "flex",
          flexDirection: "row",
          alignItems: "center",
          height: boxSize,
          gap: width * 0.015,
          transition: "none",
        }}
      >
        {/* LOGO BOX */}
        <div
          style={{
            width: boxSize,
            height: boxSize,
            backgroundColor: primaryBoxColor,
            borderRadius: "20px",
            display: "flex",
            justifyContent: "center",
            alignItems: "center",
            transform: `scale(${logoScale}) rotate(${logoRotate}deg)`,
            border: `1px solid rgba(255, 255, 255, 0.08)`,
            boxShadow: `0 8px 32px rgba(0, 0, 0, 0.4), 0 0 20px ${accentColor}30`,
            zIndex: 10,
            transition: "none",
          }}
        >
          {logoImage && (
            <img
              src={logoImage}
              style={{
                width: boxSize * (logoSize / 100),
                height: boxSize * (logoSize / 100),
                objectFit: "contain",
                filter: "drop-shadow(0px 2px 4px rgba(0,0,0,0.5))",
                transition: "none",
              }}
              alt="Logo"
            />
          )}
        </div>

        {/* TEXT PANEL */}
        <div
          style={{
            height: panelHeight,
            width: panelWidth,
            backgroundColor: panelColor,
            borderRadius: "16px",
            overflow: "hidden",
            position: "relative",
            backdropFilter: "blur(12px)",
            WebkitBackdropFilter: "blur(12px)",
            border: `1px solid rgba(255, 255, 255, 0.05)`,
            borderLeft: `5px solid ${accentColor}`,
            boxShadow: "0 4px 24px rgba(0,0,0,0.2)",
            zIndex: 5,
            transition: "none",
          }}
        >
          {/* Accent Scanning Line (Top edge) */}
          <div
            style={{
              position: "absolute",
              top: 0,
              left: 0,
              height: "3px",
              width: lineWidth,
              backgroundColor: accentColor,
              boxShadow: `0 0 10px ${accentColor}`,
              transition: "none",
            }}
          />

          {/* Text Container (Fixed width to prevent squishing while panel opens) */}
          <div
            style={{
              minWidth: targetPanelWidth,
              height: "100%",
              display: "flex",
              flexDirection: "column",
              justifyContent: "center",
              paddingLeft: width * 0.025,
              paddingRight: width * 0.025,
              opacity: textOpacity,
              transform: `translateY(${textTranslateY}px)`,
              transition: "none",
            }}
          >
            <h1
              style={{
                fontFamily: '"Space Grotesk", sans-serif',
                fontWeight: 700,
                fontSize: height * 0.055,
                color: textColor,
                margin: 0,
                padding: 0,
                lineHeight: 1.1,
                letterSpacing: "-0.02em",
                transition: "none",
              }}
            >
              {nameText}
            </h1>
            <h2
              style={{
                fontFamily: '"Inter", sans-serif',
                fontWeight: 400,
                fontSize: height * 0.030,
                color: titleColor,
                margin: 0,
                padding: 0,
                marginTop: height * 0.008,
                lineHeight: 1.2,
                letterSpacing: "0.04em",
                textTransform: "uppercase",
                transition: "none",
              }}
            >
              {titleText}
            </h2>
          </div>
        </div>
      </div>
    </AbsoluteFill>
  );
};

export default TechLowerThird;